const starCrystalSheet=new Image();starCrystalSheet.assetSrc='assets/star-crystal-v1.png';
function beginStarCrystal(e){e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'starManaFeast',bespoke:true,windup:1.2,origin:{x:e.x,y:e.y},drained:0,siphoned:false,connected:false,target:null,fired:false};}
const starCrystalAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r11e1')return starCrystalAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='starManaFeast'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=300&&clear){beginStarCrystal(e);return;}e.state='idle';if(d>800&&!e.aware)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,64*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;
 if(!a.siphoned&&e.elapsed>=1.2){a.siphoned=true;if(dist(a.origin,p)<=300&&lineClear(a.origin,p)&&!(p.inv>0)){a.connected=true;a.drained=Math.min(20,Math.max(0,Number.isFinite(p.mp)?p.mp:0));p.mp=Math.max(0,(Number.isFinite(p.mp)?p.mp:0)-a.drained);a.target={x:p.x,y:p.y};playSound('impact',e.x,e.y);}}
 if(!a.fired&&e.elapsed>=2.4){a.fired=true;e.struck=true;if(a.connected&&dist(a.target,p)<=120&&lineClear(a.origin,a.target)&&lineClear(a.target,p))hurt(60+a.drained*3);playSound('impact',e.x,e.y);}
 if(e.elapsed>=3.4){e.attack=null;e.state='idle';e.t=3.5;}
};
const starCrystalDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r11e1'||!starCrystalSheet.complete||!starCrystalSheet.naturalWidth||!starCrystalSheet.naturalHeight)return starCrystalDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0),a=e.attack;if(e.hp<=0)f={row:2,col:3};else if(a?.pattern==='starManaFeast')f={row:2,col:e.elapsed<1.2?0:e.elapsed<2.4?1:e.elapsed<2.65?2:3};let q=project(e.x,e.y),sw=starCrystalSheet.naturalWidth/4,sh=starCrystalSheet.naturalHeight/3,w=245,h=w*sh/sw,anchor=[[.86,.86,.86,.86],[.86,.86,.86,.86],[.86,.86,.86,.86]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y-12-Math.sin((e.anim||0)*2)*3);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,starCrystalSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(starCrystalSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const starCrystalSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r11e1'?175:starCrystalSizeBase(e);
const starCrystalGroundBase=drawGroundEffects;drawGroundEffects=()=>{starCrystalGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r11e1'):enemies)){let a=e.attack;if(e.species!=='r11e1'||e.hp<=0||a?.pattern!=='starManaFeast'||!visibleAt(e.x,e.y))continue;if(!a.siphoned){groundRing(e.x,e.y,300,'#8eb5ee',1);let q=project(e.x,e.y),v=project(p.x,p.y);ctx.save();ctx.strokeStyle='#8eb5ee';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(q.x,q.y-20);ctx.lineTo(v.x,v.y-20);ctx.stroke();ctx.restore();}else if(a.target&&e.elapsed<2.7){groundRing(a.target.x,a.target.y,120,a.fired?'#f7d2ff':'#ca9cdb',2+a.drained/10);if(!a.fired)groundRing(a.target.x,a.target.y,120*Math.min(1,(e.elapsed-1.2)/1.2),'#c39be0',1);}}};
if(typeof registerDirectEnemy==='function')registerDirectEnemy('r11e1',animateEnemy,drawRegionEnemy);
